#!/usr/bin/env bash
# Generated by cloudcc. Builds a deployment artefact for each execution unit.
#
# Pulumi does not install dependencies for you, so this runs before
# `pulumi up`. `cloudcc deploy` invokes it automatically.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$here"

build="build"
rm -rf "$build"
mkdir -p "$build"

echo "packaging execution unit web (container)"
if command -v docker >/dev/null 2>&1; then
  docker build --quiet --tag "cloudcc-web:latest" "web" >/dev/null
  echo "  built image cloudcc-web:latest"
  echo "  push it after \`pulumi up\` with bin/push-images.sh"
else
  echo "  docker is not installed; skipping the image build for web" >&2
  echo "  install it with: brew install --cask docker" >&2
fi

echo "packaging complete"
